#include <vector>

class Solution {
public:
    int findSpecialInteger(std::vector<int>& arr) {
        int span = arr.size() / 4;
        for (int i = 0; i < (int)arr.size() - span; ++i) {
            if (arr[i] == arr[i + span]) return arr[i];
        }
        return arr[0];
    }
};

class Solution {
    public int findSpecialInteger(int[] arr) {
        int span = arr.length / 4;
        for (int i = 0; i < arr.length - span; i++) {
            if (arr[i] == arr[i + span]) return arr[i];
        }
        return arr[0];
    }
}

var findSpecialInteger = function(arr) {
    const span = Math.floor(arr.length / 4);
    for (let i = 0; i < arr.length - span; i++) {
        if (arr[i] === arr[i + span]) return arr[i];
    }
    return arr[0];
};
